"""
models.py - Broken job data models and transitions for BENCH-008.
"""
from dataclasses import dataclass
from enum import Enum
from typing import Any, Dict, Optional, Set, Union


class JobStatus(str, Enum):
    PENDING = "PENDING"
    RUNNING = "RUNNING"
    COMPLETED = "COMPLETED"
    DLQ = "DLQ"


class InvalidTransitionError(ValueError):
    """Raised when a disallowed state transition is attempted."""
    pass


class LeaseError(RuntimeError):
    """Raised when lease ownership validation fails."""
    pass


def validate_transition(
    from_status: JobStatus,
    to_status: JobStatus,
) -> None:
    """Raise when a job state change is not part of the queue lifecycle."""
    try:
        source = JobStatus(from_status)
        target = JobStatus(to_status)
    except (TypeError, ValueError) as exc:
        raise InvalidTransitionError(f"Unknown job status: {exc}") from exc
    allowed: Dict[JobStatus, Set[JobStatus]] = {
        JobStatus.PENDING: {JobStatus.RUNNING, JobStatus.DLQ},
        JobStatus.RUNNING: {
            JobStatus.COMPLETED, JobStatus.PENDING, JobStatus.DLQ, JobStatus.RUNNING
        },
        JobStatus.COMPLETED: set(),
        JobStatus.DLQ: set(),
    }
    if target not in allowed[source]:
        raise InvalidTransitionError(f"Cannot transition from {source.value} to {target.value}")


@dataclass
class Job:
    job_id: str
    payload: Dict[str, Any]
    status: JobStatus = JobStatus.PENDING
    attempts: int = 0
    max_attempts: int = 3
    lease_owner: Optional[str] = None
    lease_expires_at: Optional[float] = None
    available_at: float = 0.0
    last_error: Optional[str] = None
    created_at: float = 0.0
    updated_at: float = 0.0

    def __post_init__(self) -> None:
        if self.attempts < 0 or self.max_attempts < 1 or self.attempts > self.max_attempts:
            raise ValueError("attempts must be >= 0 and <= max_attempts, and max_attempts >= 1")
        try:
            self.status = JobStatus(self.status)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid job status: {self.status!r}") from exc
        if self.status == JobStatus.RUNNING:
            if not isinstance(self.lease_owner, str) or not self.lease_owner.strip():
                raise ValueError("RUNNING jobs require a non-empty lease_owner")
            if self.lease_expires_at is None:
                raise ValueError("RUNNING jobs require lease_expires_at")
        elif self.lease_owner is not None or self.lease_expires_at is not None:
            raise ValueError("Non-RUNNING jobs cannot hold a lease")
