retry.py - Broken backoff calculation for BENCH-008.
"""
import random
import math
from typing import Optional


def compute_backoff(
    attempt: int,
    base: float = 0.1,
    cap: float = 5.0,
    rng: Optional[random.Random] = None,
) -> float:
    """Return full-jitter exponential backoff, bounded by ``cap``."""
    if isinstance(attempt, bool) or not isinstance(attempt, int) or attempt < 0:
        raise ValueError("attempt must be a non-negative integer")
    if base < 0 or cap < 0:
        raise ValueError("base and cap must be non-negative")
    source = rng if rng is not None else random.Random()
    if base == 0 or cap == 0:
        upper = 0.0
    elif base >= cap:
        upper = float(cap)
    else:
        try:
            upper = min(float(cap), math.ldexp(float(base), attempt))
        except OverflowError:
            upper = float(cap)
    # Guard against floating point rounding at extreme finite inputs.
    upper = min(float(cap), max(0.0, upper))
    return source.uniform(0.0, upper)
